function decodeBase64ToBytes(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

let cached = null;

/**
 * 懒加载 Draco 解码器（wasm 内联，约 266KB）。
 * 只有真正遇到 Draco 瓦片时才会编译，标准 / MeshOpt 瓦片不受影响。
 * @returns {Promise<any>} draco 模块（Decoder / Mesh / PointCloud / Draco*Array / destroy）
 */
export default function loadDracoModule() {
  if (!cached) {
    cached = DracoDecoderModule({
      wasmBinary: decodeBase64ToBytes(DRACO_WASM_BASE64),
    });
  }
  return cached;
}
